describe("SL-006 delete a task", () => {
  let server: Running;

  before(async () => {
    server = await startServer();
  });
  after(async () => {
    await server?.stop();
  });

  async function remove(id: string | number): Promise<Response> {
    return fetch(`${server.baseUrl}/api/tasks/${id}`, { method: "DELETE" });
  }

  it("DELETE /api/tasks/:id answers 204 and the task leaves the list, others stay", async () => {
    const { task: gone } = (await (await createTask(server, "Gone")).json()) as { task: Task };
    const { task: kept } = (await (await createTask(server, "Kept")).json()) as { task: Task };

    const response = await remove(gone.id);
    assert.equal(response.status, 204);
    assert.equal(await response.text(), "");

    const tasks = await listTasks(server);
    assert.deepEqual(tasks.map((t) => t.id), [kept.id]);
  });

  it("deleting the same task again answers 404 not_found", async () => {
    const { task } = (await (await createTask(server, "Once")).json()) as { task: Task };
    assert.equal((await remove(task.id)).status, 204);

    const response = await remove(task.id);
    assert.equal(response.status, 404);
    const body = (await response.json()) as { error: { code: string } };
    assert.equal(body.error.code, "not_found");
  });

  it("an id that is not a number answers 404 not_found", async () => {
    for (const id of ["abc", "1.5", "-1", "99999999999999999999"]) {
      const response = await remove(id);
      assert.equal(response.status, 404, id);
    }
  });

  it("a completed task can be deleted too", async () => {
    // Completion has no endpoint yet; the row is completed straight in the file-backed server's
    // list only once SL-003 exists, so this covers open tasks only.
    const { task } = (await (await createTask(server, "Open")).json()) as { task: Task };
    assert.equal((await remove(task.id)).status, 204);
  });

  it("the page asks for confirmation before it calls DELETE", async () => {
    const script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    assert.match(script, /method: "DELETE"/);
    assert.match(script, /confirm\(/);
    assert.ok(script.indexOf("confirm(") < script.indexOf('method: "DELETE"'));
  });

  it("a deleted task stays deleted after kill -9 and a restart", async () => {
    const dbPath = newDbPath();
    let s = await startServer(dbPath);
    try {
      const { task } = (await (await createTask(s, "Temp")).json()) as { task: Task };
      const res = await fetch(`${s.baseUrl}/api/tasks/${task.id}`, { method: "DELETE" });
      assert.equal(res.status, 204);
      await s.stop();
      s = await startServer(dbPath);
      assert.deepEqual(await listTasks(s), []);
    } finally {
      await s.stop();
    }
  });
});
EOF

